The template controls its own copying (`__deepcopy__`), which is the Prototype pattern in idiomatic Python: mutable data is cloned and the expensive client is shared. The registry owns a private copy on registration, returns a clone on every `get`, and guards the check-then-add with a lock. Provider registration by `__init_subclass__` is the lightweight plugin hook, with duplicate detection; real third-party plugins would add entry points on top.

**`protoreg.py`**

```python
import copy
import threading
from typing import Any, ClassVar


class HttpClient:
    """Stand-in for an expensive, non-copyable resource (it owns a lock)."""

    def __init__(self) -> None:
        self.lock = threading.Lock()


class PromptTemplate:
    def __init__(self, name: str, system: str, examples: list[str], client: HttpClient) -> None:
        self.name = name
        self.system = system
        self.examples = examples
        self.client = client            # shared on purpose
        self.parent: "PromptTemplate | None" = None

    def __deepcopy__(self, memo: dict[int, Any]) -> "PromptTemplate":
        clone = type(self).__new__(type(self))
        memo[id(self)] = clone          # register first so cycles resolve
        clone.name = self.name
        clone.system = self.system
        clone.examples = copy.deepcopy(self.examples, memo)
        clone.client = self.client      # never copy the client
        clone.parent = copy.deepcopy(self.parent, memo)
        return clone


class TemplateRegistry:
    def __init__(self) -> None:
        self._templates: dict[str, PromptTemplate] = {}
        self._lock = threading.Lock()

    def register(self, template: PromptTemplate) -> None:
        with self._lock:
            if template.name in self._templates:
                raise KeyError(f"already registered: {template.name}")
            self._templates[template.name] = copy.deepcopy(template)  # own a private copy

    def get(self, name: str) -> PromptTemplate:
        with self._lock:
            try:
                stored = self._templates[name]
            except KeyError:
                raise KeyError(f"unknown template {name!r}; known: {sorted(self._templates)}") from None
            return copy.deepcopy(stored)

    def names(self) -> list[str]:
        with self._lock:
            return sorted(self._templates)


class Provider:
    registry: ClassVar[dict[str, type["Provider"]]] = {}

    def __init_subclass__(cls, /, name: str | None = None, **kwargs: Any) -> None:
        super().__init_subclass__(**kwargs)
        key = name or cls.__name__.removesuffix("Provider").lower()
        if key in Provider.registry:
            raise TypeError(f"duplicate provider {key!r}")
        Provider.registry[key] = cls

    @classmethod
    def create(cls, name: str, **kwargs: Any) -> "Provider":
        try:
            provider_cls = Provider.registry[name]
        except KeyError:
            raise KeyError(f"unknown provider {name!r}; known: {sorted(Provider.registry)}") from None
        return provider_cls(**kwargs)
```

**`test_protoreg.py`**

```python
import copy
import threading

import pytest

from protoreg import HttpClient, PromptTemplate, Provider, TemplateRegistry


def make_template(client: HttpClient, name: str = "welcome") -> PromptTemplate:
    return PromptTemplate(name, "Be terse.", ["Q: hi"], client)


def test_clone_is_independent_but_shares_the_client() -> None:
    client = HttpClient()
    original = make_template(client)
    clone = copy.deepcopy(original)
    clone.examples.append("Q: bye")
    assert original.examples == ["Q: hi"]
    assert clone.client is original.client


def test_plain_deepcopy_of_the_client_fails() -> None:
    with pytest.raises(TypeError):
        copy.deepcopy(HttpClient())


def test_memo_handles_cycles_and_preserves_sharing() -> None:
    client = HttpClient()
    a, b = make_template(client, "a"), make_template(client, "b")
    a.parent, b.parent = b, a
    a2 = copy.deepcopy(a)
    assert a2.parent is not b and a2.parent.parent is a2
    assert a2.client is client


def test_get_returns_a_fresh_clone_every_time() -> None:
    registry = TemplateRegistry()
    registry.register(make_template(HttpClient()))
    first = registry.get("welcome")
    first.examples.append("leaked?")
    first.system = "changed"
    second = registry.get("welcome")
    assert second.examples == ["Q: hi"] and second.system == "Be terse."
    assert first is not second


def test_registry_keeps_a_private_copy_of_what_was_registered() -> None:
    registry = TemplateRegistry()
    template = make_template(HttpClient())
    registry.register(template)
    template.examples.append("mutated after register")
    assert registry.get("welcome").examples == ["Q: hi"]


def test_unknown_name_raises_with_known_names() -> None:
    registry = TemplateRegistry()
    registry.register(make_template(HttpClient()))
    with pytest.raises(KeyError, match="welcome"):
        registry.get("welcom")


def test_duplicate_registration_from_many_threads_succeeds_exactly_once() -> None:
    registry = TemplateRegistry()
    client = HttpClient()
    barrier = threading.Barrier(8)
    outcomes: list[str] = []

    def worker() -> None:
        barrier.wait()
        try:
            registry.register(make_template(client))
            outcomes.append("ok")
        except KeyError:
            outcomes.append("dup")

    threads = [threading.Thread(target=worker) for _ in range(8)]
    for t in threads:
        t.start()
    for t in threads:
        t.join()
    assert outcomes.count("ok") == 1 and outcomes.count("dup") == 7


def test_providers_register_on_subclassing_and_reject_duplicates() -> None:
    class OpenAIProvider(Provider, name="test-openai"):
        def __init__(self, model: str = "m") -> None:
            self.model = model

    class LocalProvider(Provider):
        pass

    assert Provider.registry["test-openai"] is OpenAIProvider
    assert "local" in Provider.registry
    assert Provider.create("test-openai", model="x").model == "x"
    with pytest.raises(TypeError, match="duplicate"):
        class Again(Provider, name="test-openai"):
            pass
    with pytest.raises(KeyError, match="known"):
        Provider.create("nope")
```

